--设置上赛季结算界面内容
function LadderCompetitionSeasonSettlementDialog:SetLastSeasonInfo()
    local ladderCompetionUtils = import("Game.UI.LadderCompetion.LadderCompetionUtils")
    ---@type LadderGradeVo
    local ladderGradeVo  = ladderCompetionUtils.GetGradeVo(self.lastSegment, self.lastSubSegment)
    CfUtils.FillText(self.TxtName, ladderGradeVo.name2)
    CfUtils.FillImage(self.ImgPosition, ladderGradeVo.icon)
    CfUtils.FillText(self.TxtTitle, localize('赛季结算'))
    CfUtils.FillText(self.TxtState, localize('恭喜上赛季获得'))
    CfUtils.FillText(self.TxtIntegralName, localize('上赛季积分'))
    CfUtils.FillText(self.TxtName, self.lastScore)
    local starCount = checkNumber(self.lastSubSegment)
    for i = 1, 5 do
        local child = self.StarGroup.transform:GetChild(i - 1)
        if i <= starCount then
            KTool.SetActive(child.gameObject,true)
        else
            KTool.SetActive(child.gameObject,false)
        end
    end
end

--设置本赛季开始界面内容
function LadderCompetitionSeasonSettlementDialog:SetSeasonInfo()
    local ladderCompetionUtils = import("Game.UI.LadderCompetion.LadderCompetionUtils")
    ---@type LadderGradeVo
    local ladderGradeVo  = ladderCompetionUtils.GetGradeVo(self.segment, self.subSegment)
    CfUtils.FillText(self.TxtName, ladderGradeVo.name2)
    CfUtils.FillImage(self.ImgPosition, ladderGradeVo.icon)
    CfUtils.FillText(self.TxtTitle, localize('赛季开始'))
    CfUtils.FillText(self.TxtState, localize('本季段位'))
    CfUtils.FillText(self.TxtIntegralName, localize('本赛季开始积分'))
    CfUtils.FillText(self.TxtName, self.score)
    local starCount = checkNumber(self.subSegment)
    for i = 1, 5 do
        local child = self.StarGroup.transform:GetChild(i - 1)
        if i <= starCount then
            KTool.SetActive(child.gameObject,true)
        else
            KTool.SetActive(child.gameObject,false)
        end
    end
end

