        if index == 1 then
            CfUtils.PlayAnimation(self.Root, 'LadderCompetionSeasonSettlementDialog_End')
            animTime = CfUtils.GetAnimationTime(self.Root, 'LadderCompetionSeasonSettlementDialog_End')
        else
            CfUtils.PlayAnimation(self.Root, 'LadderCompetionSeasonSettlementDialog_Begin')
            animTime = CfUtils.GetAnimationTime(self.Root, 'LadderCompetionSeasonSettlementDialog_Begin')
        end
        coroutine.yield(CS.UnityEngine.WaitForSeconds(animTime))

        -- remove blocker
        UIRaycastBlocker:RemoveCondition(ANIM_ACTION_BLOCKER_NAME)

        -- finish callback
        if finishCB then finishCB() end

        self.animActionCo_ = nil
    end)
end

